// BulkCloneUploadPage.js
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";

/* ============================================================
   PARTICLES (SAME STYLE AS SolidBulkUploadPage)
============================================================ */
function FloatingParticles() {
    const [particles, setParticles] = useState([]);

    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    return (
        <div style={styles.particles}>
            {particles.map((p) => (
                <div
                    key={p.id}
                    style={{
                        ...styles.particle,
                        left: `${p.left}%`,
                        top: `${p.top}vh`,
                        animationDelay: `${p.delay}s`,
                        animationDuration: `${p.duration}s`,
                    }}
                />
            ))}
        </div>
    );
}

/* ============================================================
   MAIN PAGE — BULK UPLOAD FOR CODE CLONE
============================================================ */
function BulkCloneUploadPage() {
    const { studyId } = useParams();
    const navigate = useNavigate();

    const [csvFile, setCsvFile] = useState(null);
    const [zipFile, setZipFile] = useState(null);

    const [csvPreview, setCsvPreview] = useState([]);

    const [processing, setProcessing] = useState(false);
    const [progress, setProgress] = useState(0);
    const [done, setDone] = useState(false);

    /* ============================================================
       CSV PREVIEW
    ============================================================ */
    const parseCsvPreview = (file) => {
        const reader = new FileReader();
        reader.onload = function (e) {
            const lines = e.target.result.split("\n").slice(0, 6);
            setCsvPreview(lines);
        };
        reader.readAsText(file);
    };


    const handleCsvChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setCsvFile(file);
            parseCsvPreview(file);
        }
    };

    const handleZipChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setZipFile(file);
        }
    };


    /* ============================================================
       UPLOAD PROCESS
    ============================================================ */
    const handleUpload = async () => {
        if (!csvFile || !zipFile) {
            alert("Please select both CSV and ZIP files.");
            return;
        }

        const token = localStorage.getItem("token");
        if (!token) {
            alert("You must be logged in.");
            return;
        }

        try {
            setProcessing(true);
            setProgress(10);

            const formData = new FormData();
            formData.append("csv", csvFile);
            formData.append("zip", zipFile);

            setProgress(25);

            const response = await fetch(
                `http://localhost:8080/api/bulk/clone/${studyId}`,
                {
                    method: "POST",
                    headers: {
                        "Authorization": `Bearer ${token}`,
                    },
                    body: formData,
                }
            );

            if (!response.ok) {
                console.error(await response.text());
                alert("Bulk upload failed.");
                setProcessing(false);
                setProgress(0);
                return;
            }

            setProgress(100);
            setDone(true);

        } catch (err) {
            console.error("Bulk upload error:", err);
            alert("Unexpected error. Check console.");
            setProgress(0);
        } finally {
            setProcessing(false);
        }
    };

    /* Redirect after finishing */
    useEffect(() => {
        if (done && progress === 100) {
            const timer = setTimeout(() => {
                navigate(`/manage-tasks/${studyId}`);
            }, 1200);

            return () => clearTimeout(timer);
        }
    }, [done, progress, navigate, studyId]);


    return (
        <div style={styles.container}>
            <FloatingParticles />

            {/* NAV */}
            <div style={styles.navbar}>
                <h2 style={styles.navTitle}>📦 Bulk Upload — Code Clone</h2>

                <button
                    style={styles.backButton}
                    onClick={() => navigate(`/manage-tasks/${studyId}`)}
                >
                    ← Back
                </button>
            </div>

            <div style={styles.wrapper}>
                <div style={styles.card}>
                    <h3 style={styles.title}>Upload CSV + ZIP (patches)</h3>

                    {/* CSV BOX */}
                    <label style={styles.uploadBox}>
                        <input
                            type="file"
                            accept=".csv"
                            style={{ display: "none" }}
                            onChange={handleCsvChange}
                        />
                        {csvFile ? (
                            <span>📄 {csvFile.name}</span>
                        ) : (
                            <span>Select CSV File</span>
                        )}
                    </label>

                    {/* CSV PREVIEW */}
                    {csvPreview.length > 0 && (
                        <div style={styles.previewBox}>
                            {csvPreview.map((line, i) => (
                                <div key={i}>{line}</div>
                            ))}
                        </div>
                    )}

                    {/* ZIP BOX */}
                    <label style={styles.uploadBox}>
                        <input
                            type="file"
                            accept=".zip"
                            style={{ display: "none" }}
                            onChange={handleZipChange}
                        />
                        {zipFile ? (
                            <span>📦 {zipFile.name}</span>
                        ) : (
                            <span>Select ZIP File</span>
                        )}
                    </label>

                    {/* Upload Button */}
                    <button
                        style={styles.uploadButton}
                        disabled={processing}
                        onClick={handleUpload}
                    >
                        {processing ? "Processing..." : "Start Bulk Upload"}
                    </button>

                    {/* PROGRESS */}
                    {(processing || done) && (
                        <>
                            <div style={styles.progressBackground}>
                                <div
                                    style={{
                                        ...styles.progressFill,
                                        width: `${progress}%`,
                                    }}
                                />
                            </div>
                            <p style={styles.progressLabel}>{progress}%</p>
                        </>
                    )}

                    {done && (
                        <p style={styles.doneMessage}>
                            ✔ All clone tasks created successfully!
                        </p>
                    )}
                </div>
            </div>

            <style>
                {`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: .4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }
                `}
            </style>
        </div>
    );
}

/* ============================================================
   STYLES (Identical to your Solid page)
============================================================ */
const styles = {
    container: {
        minHeight: "100vh",
        background: "linear-gradient(135deg, #0a0a0a, #16213e)",
        color: "#fff",
        fontFamily: "Inter, sans-serif",
        overflow: "hidden",
        position: "relative",
    },
    particles: {
        position: "fixed",
        top: 0,
        left: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
        zIndex: 0,
    },
    particle: {
        position: "absolute",
        width: "4px",
        height: "4px",
        background: "linear-gradient(135deg, #06b6d4, #8b5cf6)",
        borderRadius: "50%",
        animation: "floatParticle linear infinite",
        opacity: 0.45,
    },
    navbar: {
        display: "flex",
        justifyContent: "space-between",
        padding: "20px 40px",
        background: "rgba(255,255,255,0.03)",
        borderBottom: "1px solid rgba(255,255,255,0.1)",
    },
    navTitle: {
        fontSize: "1.5rem",
        fontWeight: "700",
        color: "#60a5fa",
    },
    backButton: {
        background: "rgba(220,38,38,0.15)",
        border: "2px solid rgba(220,38,38,0.55)",
        color: "#fca5a5",
        padding: "8px 20px",
        borderRadius: "10px",
        cursor: "pointer",
        fontWeight: "600",
        boxShadow: "0 0 12px rgba(220,38,38,0.35)",
        transition: "0.2s ease",
    },
    wrapper: {
        width: "90%",
        maxWidth: "600px",
        margin: "40px auto",
    },
    card: {
        background: "rgba(255,255,255,0.05)",
        padding: "30px",
        borderRadius: "18px",
        border: "1px solid rgba(255,255,255,0.12)",
        textAlign: "center",
        boxShadow: "0 0 20px rgba(0,0,0,0.3)",
    },
    title: {
        fontSize: "1.3rem",
        fontWeight: "700",
        marginBottom: "20px",
    },
    uploadBox: {
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: "100%",
        padding: "20px",
        borderRadius: "12px",
        border: "2px dashed rgba(255,255,255,0.25)",
        background: "rgba(255,255,255,0.03)",
        cursor: "pointer",
        marginBottom: "20px",
        boxSizing: "border-box",
    },
    previewBox: {
        background: "rgba(0,0,0,0.35)",
        padding: "15px",
        fontFamily: "monospace",
        fontSize: "0.85rem",
        borderRadius: "10px",
        marginBottom: "20px",
        textAlign: "left",
        border: "1px solid rgba(255,255,255,0.15)",
    },
    uploadButton: {
        width: "100%",
        padding: "14px",
        borderRadius: "12px",
        background: "linear-gradient(135deg, #10b981, #059669)",
        color: "white",
        fontWeight: "700",
        border: "none",
        cursor: "pointer",
        marginBottom: "20px",
        transition: "0.25s",
    },
    progressBackground: {
        width: "100%",
        height: "12px",
        background: "rgba(255,255,255,0.10)",
        borderRadius: "10px",
        marginTop: "10px",
    },
    progressFill: {
        height: "100%",
